let selectedCompare=read('vpj_compare',[]),searchesVPJ=read('vpj_searches',[]),ownedJobsVPJ=read('vpj_owned_jobs',[]),applicationRecords=read('vpj_application_records',[]);const initialJobsVPJ=jobs.map(j=>j.id);for(const j of ownedJobsVPJ){if(!jobs.some(x=>x.id===j.id))jobs.push(j)}
