function sourceSearchUrl(domain,query){return 'https://www.google.com/search?q='+encodeURIComponent('site:'+domain+' '+query+' Vĩnh Phúc')}
function renderSources(){const q=$('#sourceQuery').value.trim();$('#sourceGrid').innerHTML=sourcesVPJ.map(s=>`<article class="source-card"><div class="source-monogram" style="background:${s.color}">${s.symbol}</div><h3>${s.name}</h3><p>${s.desc}</p><div class="actions"><a class="btn primary" href="${s.url}" target="_blank" rel="noopener noreferrer">Mở nền tảng ↗</a><a class="btn" href="${sourceSearchUrl(s.domain,q)}" target="_blank" rel="noopener noreferrer">Tìm qua Google ↗</a></div><p class="page-note" style="font-size:10px;margin-bottom:0;min-height:0">Nguồn ngoài · Chưa đồng bộ dữ liệu với VPJ</p></article>`).join('')}
$('#refreshSources').onclick=renderSources;$('#sourceQuery').addEventListener('keydown',e=>{if(e.key==='Enter')renderSources()});renderSources();
$('#categoryGrid').innerHTML=[['Sản xuất','▦','Sản xuất / Công nhân'],['QC','◎','QC / QA'],['Kỹ thuật','⚙','Kỹ thuật / Cơ khí'],['Văn phòng','▤','Hành chính / Văn phòng'],['Kế toán','▥','Kế toán / Tài chính'],['Dịch vụ','↗','Bán hàng / Dịch vụ']].map(([c,ic,t])=>`<button class="category-tile" data-categorypick="${c}"><i>${ic}</i><strong>${t}</strong><small>${jobs.filter(j=>j.category===c&&!j.owned).length} vị trí minh họa</small></button>`).join('');$$('[data-categorypick]').forEach(b=>b.onclick=()=>{reset();$$('input[name=category]').forEach(x=>x.checked=x.value===b.dataset.categorypick);render();$('#resultCount').scrollIntoView({behavior:'smooth',block:'center'})});
const baseCardVPJ=card;card=function(j){return baseCardVPJ(j).replace('</article>',`<label class="compare-toggle"><input type="checkbox" data-compare="${j.id}" ${selectedCompare.includes(j.id)?'checked':''}>Thêm vào so sánh</label></article>`)};
const originalRenderVPJ=render;render=function(){originalRenderVPJ();const exp=$('#experienceFilter').value;if(exp){const cats=$$('input[name=category]:checked').map(x=>x.value),types=$$('input[name=type]:checked').map(x=>x.value),q=norm($('#query').value.trim()),loc=$('#location').value,min=+$('#salaryFilter').value;let filtered=jobs.filter(j=>j.status!=='paused'&&(!q||norm(j.title+' '+j.company+' '+j.category+' '+j.address).includes(q))&&(!loc||j.location===loc)&&(!cats.length||cats.includes(j.category))&&(!types.length||types.includes(j.type))&&j.min>=min&&(exp==='none'?j.exp==='Không cần kinh nghiệm':j.exp!=='Không cần kinh nghiệm'));filtered.sort($('#sort').value==='salary'?(a,b)=>b.max-a.max:(a,b)=>a.days-b.days);$('#jobCards').innerHTML=filtered.length?filtered.map(card).join(''):'<div class="empty">Chưa có tin phù hợp với bộ lọc.</div>';$('#resultCount').innerHTML=`<b>${filtered.length}</b> việc làm phù hợp`;}$$('#jobCards .job').forEach((c,i)=>c.hidden=!showAllVPJ&&i>=8);$('#moreBtn').style.display=showAllVPJ||$$('#jobCards .job').length<=8?'none':'inline-flex';$('#compareCount').textContent=selectedCompare.length;renderEmployer();renderApplications()};let showAllVPJ=false;$('#moreBtn').onclick=()=>{showAllVPJ=true;render()};$('#experienceFilter').onchange=render;const originalResetVPJ=reset;reset=function(){$('#experienceFilter').value='';showAllVPJ=false;originalResetVPJ()};
document.addEventListener('change',e=>{if(e.target.dataset.compare){const id=+e.target.dataset.compare;if(e.target.checked){if(selectedCompare.length>=3){e.target.checked=false;toast('So sánh tối đa 3 công việc');return}selectedCompare.push(id)}else selectedCompare=selectedCompare.filter(x=>x!==id);write('vpj_compare',selectedCompare);render()}});
$('#compareBtn').onclick=()=>{const list=jobs.filter(j=>selectedCompare.includes(j.id));if(list.length<2){toast('Chọn ít nhất 2 công việc để so sánh');return}openModal(`<h2>So sánh cơ hội</h2><p>Cân nhắc công việc theo nhu cầu của bạn.</p><div class="table-scroll"><table class="comparison"><tr><th>Tiêu chí</th>${list.map(j=>`<th>${esc(j.title)}</th>`).join('')}</tr>${[['Doanh nghiệp',j=>j.company],['Lương / tháng',j=>j.salaryText||(j.min+' – '+j.max+' triệu')],['Địa điểm',j=>j.location],['Hình thức',j=>j.type],['Kinh nghiệm',j=>j.exp]].map(([t,fn])=>`<tr><td>${t}</td>${list.map(j=>`<td>${esc(fn(j))}</td>`).join('')}</tr>`).join('')}</table></div><p class="demo-note">Thông tin từ tin mẫu trong VPJ.</p>`,true)};
$('#alertBtn').onclick=()=>{const entry={id:Date.now(),query:$('#query').value,location:$('#location').value,salary:$('#salaryFilter').value,categories:$$('input[name=category]:checked').map(x=>x.value),types:$$('input[name=type]:checked').map(x=>x.value),experience:$('#experienceFilter').value};searchesVPJ.push(entry);write('vpj_searches',searchesVPJ);showSearchesVPJ()};function showSearchesVPJ(){openModal(`<h2>Tìm kiếm đã lưu</h2><p>Mở lại bộ lọc nhanh trên thiết bị này. Chưa gửi thông báo qua email hoặc điện thoại.</p>${searchesVPJ.map(s=>`<div class="status-line"><b>${esc(s.query||'Tất cả công việc')}</b><span>${esc(s.location||'Vĩnh Phúc')} · Lương từ ${s.salary} triệu</span><div class="actions" style="margin-top:12px"><button class="btn" data-loadsearch="${s.id}">Tìm lại</button><button class="btn" data-removesearch="${s.id}">Xóa</button></div></div>`).join('')}`);$$('[data-loadsearch]').forEach(b=>b.onclick=()=>{const s=searchesVPJ.find(x=>x.id===+b.dataset.loadsearch);reset();$('#query').value=s.query;$('#location').value=s.location;$('#salaryFilter').value=s.salary;$('#experienceFilter').value=s.experience;$$('input[name=category]').forEach(x=>x.checked=s.categories.includes(x.value));$$('input[name=type]').forEach(x=>x.checked=s.types.includes(x.value));closeModal();view('jobs')});$$('[data-removesearch]').forEach(b=>b.onclick=()=>{searchesVPJ=searchesVPJ.filter(s=>s.id!==+b.dataset.removesearch);write('vpj_searches',searchesVPJ);showSearchesVPJ()})}
function renderEmployer(){const mine=jobs.filter(j=>j.owned);$('#employerMetrics').innerHTML=[[mine.length,'Tin đã tạo'],[mine.filter(j=>j.status!=='paused').length,'Tin đang mở'],[mine.filter(j=>j.status==='paused').length,'Tin tạm dừng']].map(([n,t])=>`<div class="metric"><b>${n}</b><span>${t}</span></div>`).join('');$('#employerJobs').innerHTML=mine.length?mine.map(j=>`<div class="employer-row"><div><strong>${esc(j.title)}</strong><p>${esc(j.company)} · ${esc(j.location)} · ${j.min} triệu/tháng</p><span class="pill">${j.status==='paused'?'Tạm dừng':'Đang mở'} · Tin mẫu</span></div><div class="actions"><button class="btn" data-editjob="${j.id}">Sửa tin</button><button class="btn" data-pausejob="${j.id}">${j.status==='paused'?'Mở lại':'Tạm dừng'}</button><button class="btn" data-deletejob="${j.id}">Xóa</button></div></div>`).join(''):'<div class="empty">Bạn chưa tạo tin tuyển dụng.<br>Chọn “Đăng tin mới” để bắt đầu.</div>';$$('[data-pausejob]').forEach(b=>b.onclick=()=>{const j=jobs.find(j=>j.id===+b.dataset.pausejob);j.status=j.status==='paused'?'active':'paused';persistJobs();render()});$$('[data-deletejob]').forEach(b=>b.onclick=()=>{const id=+b.dataset.deletejob;openModal('<h2>Xóa tin mẫu?</h2><p>Tin này sẽ được xóa khỏi thiết bị của bạn.</p><button class="btn primary" id="confirmDelete">Xóa tin</button>');$('#confirmDelete').onclick=()=>{const i=jobs.findIndex(j=>j.id===id);if(i>=0)jobs.splice(i,1);saved=saved.filter(x=>x!==id);selectedCompare=selectedCompare.filter(x=>x!==id);write('vpj_saved',saved);write('vpj_compare',selectedCompare);persistJobs();closeModal();render()}});$$('[data-editjob]').forEach(b=>b.onclick=()=>{const j=jobs.find(j=>j.id===+b.dataset.editjob);openModal(`<h2>Chỉnh sửa tin mẫu</h2><form class="form" id="editJobForm"><label>Vị trí<input id="editTitle" required value="${esc(j.title)}"></label><label>Doanh nghiệp<input id="editCompany" required value="${esc(j.company)}"></label><label>Mức lương (triệu)<input id="editSalary" type="number" min="1" max="200" required value="${j.min}"></label><label>Mô tả<textarea id="editDescription" required>${esc((j.desc||[]).join('\n'))}</textarea></label><button class="btn primary">Lưu tin</button></form>`);$('#editJobForm').onsubmit=e=>{e.preventDefault();j.title=$('#editTitle').value;j.company=$('#editCompany').value;j.min=+$('#editSalary').value;j.max=j.min;j.desc=[$('#editDescription').value];persistJobs();closeModal();render()}})}
