function renderApplications(){$('#appliedList').innerHTML=applied.length?jobs.filter(j=>applied.includes(j.id)).map(j=>`<div class="status-line"><b>${esc(j.title)}</b><span>${esc(j.company)}</span><button class="text-btn" data-withdraw="${j.id}">Rút ứng tuyển thử</button><p class="pill" style="display:table">Đã ghi nhận trên thiết bị · Chưa gửi doanh nghiệp</p></div>`).join(''):'Bạn chưa ứng tuyển thử công việc nào.';$$('[data-withdraw]').forEach(b=>b.onclick=()=>{applied=applied.filter(x=>x!==+b.dataset.withdraw);write('vpj_applied',applied);render()})}
const originalApplyVPJ=apply;apply=function(id){originalApplyVPJ(id);if($('#applyForm')){const f=$('#applyForm');const old=f.onsubmit;f.onsubmit=e=>{old(e);if(applied.includes(id)){applicationRecords.push({id:Date.now(),jobId:id,createdAt:new Date().toISOString(),status:'local'});write('vpj_application_records',applicationRecords);renderApplications()}}}};
