$('#cvBtn').onclick=()=>{const name=$('#profileName').value.trim();if(!name){toast('Nhập họ tên trước khi tạo CV');$('#profileName').focus();return}const data={name,phone:$('#profilePhone').value,email:$('#profileEmail').value,job:$('#profileJob').value,skills:$('#profileSkills').value,about:$('#profileAbout').value};openModal(`<h2>Xem trước CV</h2><div id="cvPreview" style="padding:25px;border:1px solid var(--line)"><h2 style="color:var(--green)">${esc(data.name)}</h2><h3>${esc(data.job||'Ứng viên')}</h3><p>${esc(data.phone)} · ${esc(data.email)}</p><hr><h3>Giới thiệu & kinh nghiệm</h3><p style="white-space:pre-wrap">${esc(data.about||'Bổ sung kinh nghiệm trong hồ sơ.')}</p><h3>Kỹ năng</h3><p>${esc(data.skills||'Bổ sung kỹ năng trong hồ sơ.')}</p></div><button class="btn primary" id="printCV" style="margin-top:20px">In / Lưu PDF</button>`,true);$('#printCV').onclick=()=>{const w=window.open('','_blank');if(!w){toast('Cho phép cửa sổ bật lên để in CV');return}w.document.write(`<!doctype html><html lang="vi"><head><title>CV — ${esc(data.name)}</title><style>body{font:15px Arial;color:#243b2f;max-width:750px;margin:50px auto;padding:25px}h2{font-size:32px}h3{margin-top:30px}p{line-height:1.7}@media print{body{margin:0}}</style></head><body>${$('#cvPreview').innerHTML}</body></html>`);w.document.close();w.focus();w.print()}};
let cvDatabaseVPJ=null;function cvDb(){return new Promise((resolve,reject)=>{const r=indexedDB.open('vpj_cv',1);r.onupgradeneeded=()=>r.result.createObjectStore('files');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}async function storeCV(file){const db=await cvDb();await new Promise((resolve,reject)=>{const t=db.transaction('files','readwrite');t.objectStore('files').put(file,'cv');t.oncomplete=resolve;t.onerror=()=>reject(t.error)});db.close()}async function getCV(){const db=await cvDb();return new Promise((resolve,reject)=>{const r=db.transaction('files').objectStore('files').get('cv');r.onsuccess=()=>{db.close();resolve(r.result)};r.onerror=()=>reject(r.error)})}
$('#uploadCvBtn').onclick=()=>$('#cvFile').click();$('#cvFile').onchange=async()=>{const f=$('#cvFile').files[0];if(!f)return;if(f.size>5*1024*1024){toast('Chọn CV nhỏ hơn 5 MB');return}const magic=new Uint8Array(await f.slice(0,5).arrayBuffer());if(String.fromCharCode(...magic)!=='%PDF-'){toast('Chọn file PDF hợp lệ');return}try{await storeCV(f);$('#cvFileLabel').textContent='Đã lưu trên thiết bị: '+f.name;toast('Đã lưu CV PDF trên thiết bị')}catch{toast('Không thể lưu CV trên trình duyệt này')}};getCV().then(f=>{if(f){$('#cvFileLabel').textContent='CV trên thiết bị: '+f.name;const b=document.createElement('button');b.className='text-btn';b.textContent=' · Xem CV';b.onclick=()=>{const url=URL.createObjectURL(f);window.open(url,'_blank','noopener');setTimeout(()=>URL.revokeObjectURL(url),60000)};$('#cvFileLabel').appendChild(b)}}).catch(()=>{});
const guideContentVPJ=[{title:'CV rõ ràng, đúng vị trí',symbol:'01',desc:'Đưa kinh nghiệm liên quan lên trước. Dùng ví dụ cụ thể thay cho mô tả chung.',body:['Ghi thông tin liên hệ chính xác và vị trí mong muốn.','Mô tả nhiệm vụ, công cụ đã sử dụng và kết quả đạt được.','Giữ bố cục dễ đọc, kiểm tra lỗi chính tả và xuất PDF.']},{title:'Chuẩn bị trước phỏng vấn',symbol:'02',desc:'Tìm hiểu công ty, đọc kỹ mô tả và chuẩn bị câu hỏi.',body:['Chuẩn bị phần giới thiệu ngắn về kinh nghiệm.','Đưa ví dụ về tình huống và cách bạn giải quyết.','Hỏi rõ công việc, ca làm, lương, phụ cấp và thời gian thử việc.']},{title:'Tìm việc có kiểm chứng',symbol:'03',desc:'Kiểm tra địa chỉ công ty và thông tin người tuyển dụng.',body:['Đối chiếu thông tin trên kênh chính thức của doanh nghiệp.','Tìm hiểu kỹ nếu bị yêu cầu chuyển tiền để giữ chỗ hoặc nhận việc.','Chỉ cung cấp thông tin cần thiết cho mục đích ứng tuyển.']}];$('#guideGrid').innerHTML=guideContentVPJ.map((g,i)=>`<article class="source-card"><span class="eyebrow">${g.symbol} / VPJ GUIDE</span><h3>${g.title}</h3><p>${g.desc}</p><button class="detail-button" data-guide="${i}">Đọc hướng dẫn ↗</button></article>`).join('');$$('[data-guide]').forEach(b=>b.onclick=()=>{const g=guideContentVPJ[+b.dataset.guide];openModal(`<h2>${g.title}</h2><p>${g.desc}</p><ul style="line-height:2;color:#617168;font-size:14px">${g.body.map(t=>`<li>${t}</li>`).join('')}</ul>`)});
